QLabel#metricLabel { color: @text_muted@; font-size: 10px; font-weight: 700; }
QLabel#metricValue { color: @text_primary@; font-size: __FONT_SIZE_KPI__px; font-weight: 900; }
QLabel#sideTitle { color: @text_primary@; font-size: 13px; font-weight: 800; }
QLabel#sideMuted { color: @text_muted@; font-size: 10px; }
