QLineEdit:focus, QComboBox:focus, QDateEdit:focus, QDoubleSpinBox:focus, QSpinBox:focus, QPlainTextEdit:focus { border: 1px solid @primary@; }
QComboBox QAbstractItemView { background: @components.forms.combo_popup@; color: @components.forms.search_text@; selection-background-color: @primary@; selection-color: @components.buttons.button_text@; }
QPushButton {
    background: @components.buttons.button@; color: @components.buttons.button_text@; border: 1px solid @components.forms.input_border@; border-radius: 10px;
    padding: 8px 14px; font-weight: __FONT_WEIGHT_BOLD__;
}
QPushButton:hover { background: @components.buttons.button_hover@; border-color: @components.buttons.primary_hover@; }
QPushButton#primaryButton, QPushButton#goldButton {
    background: @primary@; color: @components.buttons.button_text@; border-color: @components.buttons.primary_hover@; font-weight: __FONT_WEIGHT_BLACK__;
}
QPushButton#primaryButton:hover, QPushButton#goldButton:hover { background: @components.buttons.primary_hover@; color: @components.buttons.button_text@; }
QPushButton#successButton { background: @components.buttons.button_success@; color: @components.buttons.button_success_text@; border-color: @success@; }
