QPushButton#secondaryButton { background: @components.buttons.button_secondary@; color: @components.buttons.button_secondary_text@; }
QPushButton#dangerButton { background: @components.buttons.button_danger@; color: @components.buttons.button_danger_text@; border-color: @components.states.danger_border@; }
QPushButton#dangerButton:hover { background: @components.buttons.button_danger@; color: @components.buttons.button_danger_text@; border-color: @components.states.danger_border@; }
QTableWidget, QTableView, QListWidget, QListView, QTreeWidget, QTreeView {
    background: @tables.background@; alternate-background-color: @tables.alternate_background@; color: @tables.text@;
    border: 1px solid @divider@; border-radius: 12px; gridline-color: @tables.grid@;
    selection-background-color: @tables.selected_background@; selection-color: @tables.selected_text@; outline: 0;
}
QTableWidget::item { padding: 8px; }
QHeaderView::section {
    background: @tables.header_background@; color: @tables.header_text@; border: 0; padding: 10px 10px; font-weight: __FONT_WEIGHT_BLACK__;
}
QGroupBox { background: @surface@; border: 1px solid @border@; border-radius: 14px; margin-top: 10px; padding-top: 15px; font-weight: __FONT_WEIGHT_EXTRABOLD__; color: @text_primary@; }
QGroupBox::title { subcontrol-origin: margin; left: 13px; padding: 0 7px; color: @text_primary@; background: @surface@; }
QTabWidget::pane { border: 1px solid @divider@; background: @surface@; border-radius: 12px; }
QTabBar::tab { background: @components.tabs.tab@; color: @components.tabs.tab_text@; padding: 9px 16px; margin-right: 3px; border-radius: 9px; font-weight: __FONT_WEIGHT_EXTRABOLD__; }
QTabBar::tab:selected { background: @primary@; color: @components.buttons.button_text@; }
QProgressBar { background: @background@; border: 1px solid @components.progress.progress_border@; border-radius: 6px; text-align: center; color: @text_primary@; }
QProgressBar::chunk { background: @primary@; border-radius: 5px; }
QScrollArea, QAbstractScrollArea { background: @background@; border: 0; }
