QPushButton#themeToggle:checked { background:@components.theme.theme_checked_background@; color:@components.theme.on_theme_checked@; border:1px solid @primary@; }
QPushButton#themeToggle:checked:hover { background:@components.theme.theme_checked_hover@; color:@text_primary@; }
QToolTip { background: @components.navigation.sidebar@; color: @components.navigation.sidebar_text_primary@; border: 1px solid @primary@; padding: 6px; }
QAbstractItemView {
    background: @surface@; color: @text_primary@;
    alternate-background-color: @surface_alt@;
    selection-background-color: @selection_background@; selection-color: @components.theme.on_selection@;
}
QAbstractItemView::item:hover { background: @hover@; color: @text_primary@; }
QListWidget, QListView, QTreeWidget, QTreeView { border: 1px solid @border@; border-radius: 10px; }
QMenu { background: @surface@; color: @text_primary@; border: 1px solid @border@; padding: 5px; }
