/* -----------------------------------------------------------------------
   Unified application visual language
   ----------------------------------------------------------------------- */
QFrame#pageHeader[unified="true"] {
    background: qlineargradient(x1:0,y1:0,x2:1,y2:0,
        stop:0 @components.navigation.sidebar@,
        stop:0.58 @components.navigation.navigation@,
        stop:1 @info@);
    border: 1px solid @components.navigation.sidebar_border@;
    border-radius: 16px;
    min-height: 86px;
}
QFrame#pageHeader[unified="true"] QLabel#pageTitle {
    color: @components.theme.on_colored_surface@;
    font-size: 24px;
    font-weight: __FONT_WEIGHT_BLACK__;
}
QFrame#pageHeader[unified="true"] QLabel#pageSubtitle {
    color: @components.navigation.nav_text@;
    font-size: __FONT_SIZE_SUBTITLE__px;
}
QFrame#pageHeader[unified="true"] QLabel#pageMark {
    background: @primary@;
